	partial := append([]historySessionFile(nil), files...)
	partial[0].ContentDigest = ""
	if got := historyTranscriptFilesFingerprint(partial); got != "" {
		t.Fatalf("fingerprint over an unverified set = %q, want empty", got)
	}
}

